window.APSFieldReports.markup="<div class=\"r-body\">\n    <div class=\"r-heading\"><h1 id=\"r-heading\">工序报工</h1><span class=\"r-caption\">2026-09-07 · 示例数据</span></div>\n    <div class=\"r-meta\"><span>回转壳体单元</span><span>实绩统计截至 <b id=\"r-clock\">09-07 16:30</b></span><span class=\"r-inline r-amber\" id=\"r-incomplete\"></span></div>\n    <section class=\"r-kpis wb-metrics\" aria-label=\"工序完成概览\" id=\"r-kpis\" style=\"--wb-columns: 5;\"></section>\n    <div class=\"r-tools\"><div class=\"r-filters\" id=\"r-filters\" aria-label=\"完成情况筛选\"></div><label class=\"r-search\"><i data-lucide=\"search\" aria-hidden=\"true\"></i><input id=\"r-search\" type=\"search\" placeholder=\"批次 / 工序 / 人员\" aria-label=\"搜索批次、工序或人员\"></label><div class=\"r-toolbar-actions wb-actions\" role=\"group\" aria-label=\"报工操作\"><button class=\"r-action wb-action wb-transfer\" data-open-import=\"\" data-wb-transfer=\"import\"><i data-lucide=\"file-input\" aria-hidden=\"true\"></i>直接导入</button><button class=\"r-action wb-action wb-transfer\" data-export-reports=\"\" title=\"导出当前筛选的已保存报工与工序汇总\" data-wb-transfer=\"export\"><i data-lucide=\"file-output\" aria-hidden=\"true\"></i>导出报工</button><button class=\"r-action wb-action wb-transfer\" data-download-template=\"\" aria-label=\"下载报工模板\" data-tooltip=\"下载报工模板\" data-wb-transfer=\"template\"><i data-lucide=\"file-down\" aria-hidden=\"true\"></i>下载模板</button><button class=\"r-action primary\" data-add-current=\"\"><i data-lucide=\"plus\" aria-hidden=\"true\"></i>新增报工</button></div></div>\n    <div id=\"r-view\"></div>\n    <footer class=\"r-footer\"><span id=\"r-row-count\"></span><span id=\"r-save-status\" aria-live=\"polite\">示例会话 · 未连接生产数据</span></footer>\n   </div><div class=\"r-editor-layer\" id=\"r-editor-layer\" hidden=\"\"></div>";
